    f = Q("0.03"); t = Q("0.26"); cap = Q("0.8")
    def eq_post(N):
        # question's definition: A + shield - fee - total debt
        return A + t*N - f*N - (D0 + N)
    if (D0 + planned) / eq_post(planned) <= cap:
        N = planned
    else:
        N = (cap*(A - D0) - D0) / (1 + cap*(1 - t + f))
    net = N - f*N
    equity_after = eq_post(N)
    # just after issue, net proceeds still held as cash
    equity_pre = equity_after + net
    price = equity_pre / n0
    shares_after = n0 - net/price
    return {"final": shares_after, "debt_issued": N, "repurchase_price": price, "equity_after": equity_after}

